1	//! The unions a file writes for its props, member by member in written order (ADR 0026, S7a2).
2	//!
3	//! The checker returns a union's members sorted by kind, then value, and the order the author wrote is the order a
4	//! Storybook control lists the options in. This reads it from the syntax alone: the union a property signature writes,
5	//! directly or through a type alias or enum the same file declares at module level. A name the file does not declare
6	//! (an import, a global, a type reached through a namespace) is kept as the name: what it stands for is in another
7	//! file, which oxc cannot find without resolving modules.
8	
9	use compact_str::CompactString;
10	use oxc_allocator::Allocator;
11	use oxc_ast::ast::*;
12	use oxc_ast_visit::{Visit, walk};
13	use oxc_parser::{ParseOptions, Parser};
14	use oxc_span::SourceType;
15	use rustc_hash::{FxHashMap, FxHashSet};
16	
17	use super::js_text;
18	use crate::types::output::{BigIntValue, PropType, TupleElement};
19	
20	/// The property signatures of one file whose written type is a union of at least two members.
21	#[derive(Debug, Default)]
22	pub(crate) struct WrittenUnions {
23	    props: Vec<WrittenProp>,
24	}
25	
26	#[derive(Debug)]
27	struct WrittenProp {
28	    /// The interface whose body declares it; `None` for a member of a type literal.
29	    interface: Option<CompactString>,
30	    name: CompactString,
31	    members: Vec<WrittenMember>,
32	}
33	
34	/// One member of a written union, as far as the file states it.
35	#[derive(Debug, Clone, PartialEq)]
36	pub(crate) enum WrittenMember {
37	    /// A member the syntax states in full: a literal, a keyword, an array or tuple of those.
38	    Type(PropType),
39	    /// A reference to a type the file does not declare, as written (`React.ReactNode`, `Size.Small` for a member of an
40	    /// enum the file declares).
41	    Name(CompactString),
42	    /// A member of which only the kind is written: a function type, an object literal, an intersection.
43	    Kind(MemberKind),
44	}
45	
46	/// The kind of a union member whose type is not written out in full.
47	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
48	pub(crate) enum MemberKind {
49	    Function,
50	    Object,
51	    Callable,
52	    Array,
53	    Tuple,
54	    Readonly,
55	    Intersection,
56	    Template,
57	}
58	
59	impl WrittenUnions {
60	    /// The union written for prop `name` by the interface `interface` (`Some`) or by a type literal (`None`): the one
61	    /// every such declaration writes alike, or `None` when there is none or two write different unions.
62	    pub(crate) fn find(&self, interface: Option<&str>, name: &str) -> Option<&[WrittenMember]> {
63	        let mut found = self
64	            .props
65	            .iter()
66	            .filter(|prop| prop.name == name && prop.interface.as_deref() == interface)
67	            .map(|prop| prop.members.as_slice());
68	        let first = found.next()?;
69	        found.all(|other| other == first).then_some(first)
70	    }
71	}
72	
73	/// The written unions of `source`, the text of `path`. Empty for a file too deeply nested to parse safely.
74	pub(crate) fn written_unions(path: &camino::Utf8Path, source: &str) -> WrittenUnions {
75	    if super::max_bracket_nesting_depth(source) > super::MAX_SOURCE_NESTING_DEPTH {
76	        return WrittenUnions::default();
77	    }
78	    let allocator = Allocator::default();
79	    let source_type = SourceType::from_path(path).unwrap_or_default();
80	    let options = ParseOptions { preserve_parens: false, ..ParseOptions::default() };
81	    let parsed = Parser::new(&allocator, source, source_type).with_options(options).parse();
82	    let mut collector = Collector {
83	        declared: Declared::of(&parsed.program),
84	        owner: None,
85	        member_depth: 0,
86	        type_params: Vec::new(),
87	        props: Vec::new(),
88	    };
89	    collector.visit_program(&parsed.program);
90	    WrittenUnions { props: collector.props }
91	}
92	
93	/// The module-level declarations a union member can name: a name declared twice is in `ambiguous` and expands to
94	/// nothing.
95	#[derive(Default)]
96	struct Declared<'a, 's> {
97	    aliases: FxHashMap<&'s str, &'s TSTypeAliasDeclaration<'a>>,
98	    interfaces: FxHashSet<&'s str>,
99	    enums: FxHashMap<&'s str, Vec<CompactString>>,
100	    ambiguous: Vec<&'s str>,
101	}
102	
103	impl<'a, 's> Declared<'a, 's> {
104	    fn of(program: &'s Program<'a>) -> Self {
105	        let mut declared = Declared::default();
106	        for statement in &program.body {
107	            let declaration = match statement {
108	                Statement::ExportDeclaration(export) => Some(&export.declaration),
109	                _ => statement.as_declaration(),
110	            };
111	            match declaration {
112	                Some(Declaration::TSTypeAliasDeclaration(alias)) => {
113	                    let name = alias.id.name.as_str();
114	                    if declared.aliases.insert(name, &**alias).is_some() {
115	                        declared.ambiguous.push(name);
116	                    }
117	                }
118	                Some(Declaration::TSInterfaceDeclaration(interface)) => {
119	                    declared.interfaces.insert(interface.id.name.as_str());
120	                }
121	                Some(Declaration::TSEnumDeclaration(declaration)) => {
122	                    let members = declaration
123	                        .body
124	                        .members
125	                        .iter()
126	                        .filter_map(|member| match &member.id {
127	                            TSEnumMemberName::Identifier(id) => Some(CompactString::from(id.name.as_str())),
128	                            TSEnumMemberName::String(s) | TSEnumMemberName::ComputedString(s) => {
129	                                Some(CompactString::from(js_text::lossy(s.value).as_ref()))
130	                            }
131	                            TSEnumMemberName::ComputedTemplateString(_) => None,
132	                        })
133	                        .collect();
134	                    let name = declaration.id.name.as_str();
135	                    if declared.enums.insert(name, members).is_some() {
136	                        declared.ambiguous.push(name);
137	                    }
138	                }
139	                _ => {}
140	            }
141	        }
142	        declared
143	    }
144	}
145	
146	struct Collector<'a, 's> {
147	    declared: Declared<'a, 's>,
148	    /// The interface or type literal whose body is being read: `Some(Some(name))` for an interface.
149	    owner: Option<Option<CompactString>>,
150	    /// How many property signatures enclose the current node: a member of a type literal nested in another member's
151	    /// type is not a prop.
152	    member_depth: usize,
153	    /// The type parameters in scope, which shadow a module-level declaration of the same name.
154	    type_params: Vec<CompactString>,
155	    props: Vec<WrittenProp>,
156	}
157	
158	impl<'a> Visit<'a> for Collector<'a, '_> {
159	    fn visit_ts_interface_declaration(&mut self, it: &TSInterfaceDeclaration<'a>) {
160	        let scope = self.enter_type_params(it.type_parameters.as_deref());
161	        let owner = self.owner.replace(Some(CompactString::from(it.id.name.as_str())));
162	        walk::walk_ts_interface_declaration(self, it);
163	        self.owner = owner;
164	        self.type_params.truncate(scope);
165	    }
166	
167	    fn visit_ts_type_alias_declaration(&mut self, it: &TSTypeAliasDeclaration<'a>) {
168	        let scope = self.enter_type_params(it.type_parameters.as_deref());
169	        walk::walk_ts_type_alias_declaration(self, it);
170	        self.type_params.truncate(scope);
171	    }
172	
173	    fn visit_function(&mut self, it: &Function<'a>, flags: oxc_syntax::scope::ScopeFlags) {
174	        let scope = self.enter_type_params(it.type_parameters.as_deref());
175	        walk::walk_function(self, it, flags);
176	        self.type_params.truncate(scope);
177	    }
178	
179	    fn visit_arrow_function_expression(&mut self, it: &ArrowFunctionExpression<'a>) {
180	        let scope = self.enter_type_params(it.type_parameters.as_deref());
181	        walk::walk_arrow_function_expression(self, it);
182	        self.type_params.truncate(scope);
183	    }
184	
185	    fn visit_ts_type_literal(&mut self, it: &TSTypeLiteral<'a>) {
186	        let owner = self.owner.replace(None);
187	        walk::walk_ts_type_literal(self, it);
188	        self.owner = owner;
189	    }
190	
191	    fn visit_ts_property_signature(&mut self, it: &TSPropertySignature<'a>) {
192	        if self.member_depth == 0
193	            && let Some(owner) = &self.owner
194	            && let Some(name) = it.key.static_name()
195	            && let Some(annotation) = &it.type_annotation
196	        {
197	            let mut members = Vec::new();
198	            self.push_members(&annotation.type_annotation, &mut Vec::new(), &mut members);
199	            if members.len() > 1 {
200	                self.props.push(WrittenProp {
201	                    interface: owner.clone(),
202	                    name: CompactString::from(js_text::property_name(&name)),
203	                    members,
204	                });
205	            }
206	        }
207	        self.member_depth += 1;
208	        walk::walk_ts_property_signature(self, it);
209	        self.member_depth -= 1;
210	    }
211	}
212	
213	impl<'a> Collector<'a, '_> {
214	    fn enter_type_params(&mut self, params: Option<&TSTypeParameterDeclaration<'a>>) -> usize {
215	        let scope = self.type_params.len();
216	        for param in params.into_iter().flat_map(|params| &params.params) {
217	            self.type_params.push(CompactString::from(param.name.name.as_str()));
218	        }
219	        scope
220	    }
221	
222	    /// A module-level declaration named `name` that no type parameter in scope shadows and no other declaration shares.
223	    fn declares(&self, name: &str) -> bool {
224	        !self.type_params.iter().any(|param| param == name) && !self.declared.ambiguous.contains(&name)
225	    }
226	
227	    /// Appends the members `ty` writes, flattening a union and a same-file non-generic alias or enum it names. `seen`
228	    /// holds the aliases being expanded, so a recursive one (`type Json = string | Json[]`) stops.
229	    fn push_members<'s>(&'s self, ty: &'s TSType<'a>, seen: &mut Vec<&'s str>, out: &mut Vec<WrittenMember>) {
230	        match ty {
231	            TSType::TSUnionType(union) => {
232	                for member in &union.types {
233	                    self.push_members(member, seen, out);
234	                }
235	            }
236	            TSType::TSParenthesizedType(inner) => self.push_members(&inner.type_annotation, seen, out),
237	            TSType::TSTypeReference(reference) => {
238	                if let TSTypeName::IdentifierReference(id) = &reference.type_name
239	                    && reference.type_arguments.is_none()
240	                    && self.declares(id.name.as_str())
241	                {
242	                    let name = id.name.as_str();
243	                    if let Some(alias) = self.declared.aliases.get(name)
244	                        && alias.type_parameters.is_none()
245	                    {
246	                        if !seen.contains(&name) {
247	                            seen.push(name);
248	                            self.push_members(&alias.type_annotation, seen, out);
249	                            seen.pop();
250	                        }
251	                        return;
252	                    }
253	                    if let Some(members) = self.declared.enums.get(name) {
254	                        out.extend(members.iter().map(|member| WrittenMember::Name(format!("{name}.{member}").into())));
255	                        return;
256	                    }
257	                }
258	                out.extend(self.member(ty));
259	            }
260	            _ => out.extend(self.member(ty)),
261	        }
262	    }
263	
264	    /// One member as written; `None` for a type the syntax does not state (`typeof x`, `keyof T`, an indexed access, a
265	    /// conditional or mapped type).
266	    fn member(&self, ty: &TSType<'a>) -> Option<WrittenMember> {
267	        let written = |prop_type| Some(WrittenMember::Type(prop_type));
268	        let kind = |kind| Some(WrittenMember::Kind(kind));
269	        match ty {
270	            TSType::TSStringKeyword(_) => written(PropType::String),
271	            TSType::TSNumberKeyword(_) => written(PropType::Number),
272	            TSType::TSBooleanKeyword(_) => written(PropType::Boolean),
273	            TSType::TSNullKeyword(_) => written(PropType::Null),
274	            TSType::TSUndefinedKeyword(_) => written(PropType::Undefined),
275	            TSType::TSAnyKeyword(_) => written(PropType::Any),
276	            TSType::TSNeverKeyword(_) => written(PropType::Never),
277	            TSType::TSUnknownKeyword(_) => written(PropType::Unknown),
278	            TSType::TSVoidKeyword(_) => written(PropType::Void),
279	            TSType::TSBigIntKeyword(_) => written(PropType::BigInt),
280	            TSType::TSLiteralType(literal) => literal_type(&literal.literal).map(WrittenMember::Type),
281	            TSType::TSParenthesizedType(inner) => self.member(&inner.type_annotation),
282	            TSType::TSArrayType(array) => match self.member(&array.element_type) {
283	                Some(WrittenMember::Type(element)) => written(PropType::Array(Box::new(element))),
284	                _ => kind(MemberKind::Array),
285	            },
286	            TSType::TSTupleType(tuple) => {
287	                let elements: Option<Vec<TupleElement>> = tuple
288	                    .element_types
289	                    .iter()
290	                    .map(|element| match self.member(element.as_ts_type()?) {
291	                        Some(WrittenMember::Type(element)) => Some(TupleElement::required(element)),
292	                        _ => None,
293	                    })
294	                    .collect();
295	                match elements {
296	                    Some(elements) => written(PropType::Tuple(elements)),
297	                    None => kind(MemberKind::Tuple),
298	                }
299	            }
300	            TSType::TSTypeOperatorType(operator) => match operator.operator {
301	                TSTypeOperatorOperator::Readonly => match self.member(&operator.type_annotation) {
302	                    Some(WrittenMember::Type(inner)) => written(PropType::Readonly(Box::new(inner))),
303	                    _ => kind(MemberKind::Readonly),
304	                },
305	                TSTypeOperatorOperator::Keyof | TSTypeOperatorOperator::Unique => None,
306	            },
307	            TSType::TSFunctionType(_) | TSType::TSConstructorType(_) => kind(MemberKind::Function),
308	            TSType::TSTypeLiteral(_) | TSType::TSIntersectionType(_) | TSType::TSTemplateLiteralType(_) => {
309	                body_kind(ty).map(WrittenMember::Kind)
310	            }
311	            TSType::TSTypeReference(reference) => self.reference(reference),
312	            TSType::TSUnionType(_)
313	            | TSType::TSObjectKeyword(_)
314	            | TSType::TSSymbolKeyword(_)
315	            | TSType::TSIntrinsicKeyword(_)
316	            | TSType::TSThisType(_)
317	            | TSType::TSTypeQuery(_)
318	            | TSType::TSIndexedAccessType(_)
319	            | TSType::TSConditionalType(_)
320	            | TSType::TSMappedType(_)
321	            | TSType::TSInferType(_)
322	            | TSType::TSImportType(_)
323	            | TSType::TSTypePredicate(_)
324	            | TSType::TSNamedTupleMember(_)
325	            | TSType::JSDocNullableType(_)
326	            | TSType::JSDocNonNullableType(_)
327	            | TSType::JSDocUnknownType(_) => None,
328	        }
329	    }
330	
331	    /// A reference that is not a same-file alias of a union: the kind of a same-file interface or generic alias, an
332	    /// array type by its standard name, else the name as written.
333	    fn reference(&self, reference: &TSTypeReference<'a>) -> Option<WrittenMember> {
334	        let name = type_name(&reference.type_name);
335	        if let TSTypeName::IdentifierReference(id) = &reference.type_name
336	            && self.declares(id.name.as_str())
337	        {
338	            let name = id.name.as_str();
339	            if self.declared.interfaces.contains(name) {
340	                return Some(WrittenMember::Kind(MemberKind::Object));
341	            }
342	            if let Some(alias) = self.declared.aliases.get(name) {
343	                // A generic alias's members depend on its arguments, and a non-generic one named here is not flattened:
344	                // only the kind of its body is certain.
345	                return body_kind(&alias.type_annotation).map(WrittenMember::Kind);
346	            }
347	        }
348	        match name.as_str() {
349	            "Array" => Some(WrittenMember::Kind(MemberKind::Array)),
350	            "ReadonlyArray" => Some(WrittenMember::Kind(MemberKind::Readonly)),
351	            _ => Some(WrittenMember::Name(name)),
352	        }
353	    }
354	}
355	
356	/// The kind of a type as written at its top level, without following a name.
357	fn body_kind(ty: &TSType<'_>) -> Option<MemberKind> {
358	    match ty {
359	        TSType::TSArrayType(_) => Some(MemberKind::Array),
360	        TSType::TSTupleType(_) => Some(MemberKind::Tuple),
361	        TSType::TSFunctionType(_) | TSType::TSConstructorType(_) => Some(MemberKind::Function),
362	        TSType::TSTypeLiteral(literal) => Some(
363	            if literal.members.iter().any(|member| {
364	                matches!(
365	                    member,
366	                    TSSignature::TSCallSignatureDeclaration(_) | TSSignature::TSConstructSignatureDeclaration(_)
367	                )
368	            }) {
369	                MemberKind::Callable
370	            } else {
371	                MemberKind::Object
372	            },
373	        ),
374	        TSType::TSIntersectionType(_) => Some(MemberKind::Intersection),
375	        TSType::TSTemplateLiteralType(_) => Some(MemberKind::Template),
376	        TSType::TSTypeOperatorType(operator) if operator.operator == TSTypeOperatorOperator::Readonly => {
377	            Some(MemberKind::Readonly)
378	        }
379	        TSType::TSParenthesizedType(inner) => body_kind(&inner.type_annotation),
380	        _ => None,
381	    }
382	}
383	
384	fn type_name(name: &TSTypeName<'_>) -> CompactString {
385	    match name {
386	        TSTypeName::IdentifierReference(id) => CompactString::from(id.name.as_str()),
387	        TSTypeName::QualifiedName(qualified) => {
388	            let mut text = type_name(&qualified.left);
389	            text.push('.');
390	            text.push_str(qualified.right.name.as_str());
391	            text
392	        }
393	        TSTypeName::ThisExpression(_) => CompactString::from("this"),
394	    }
395	}
396	
397	fn literal_type(literal: &TSLiteral<'_>) -> Option<PropType> {
398	    match literal {
399	        TSLiteral::StringLiteral(s) => Some(PropType::StringLiteral(js_text::lossy(s.value).into_owned())),
400	        TSLiteral::NumericLiteral(n) => Some(PropType::NumberLiteral(n.value)),
401	        TSLiteral::BooleanLiteral(b) => Some(PropType::BoolLiteral(b.value)),
402	        TSLiteral::BigIntLiteral(b) => BigIntValue::parse(b.value.as_str()).map(PropType::BigIntLiteral),
403	        TSLiteral::UnaryExpression(unary) => match (&unary.operator, &unary.argument) {
404	            (UnaryOperator::UnaryNegation, Expression::NumericLiteral(n)) => Some(PropType::NumberLiteral(-n.value)),
405	            (UnaryOperator::UnaryNegation, Expression::BigIntLiteral(b)) => {
406	                BigIntValue::parse(&format!("-{}", b.value.as_str())).map(PropType::BigIntLiteral)
407	            }
408	            _ => None,
409	        },
410	        TSLiteral::TemplateLiteral(template) if template.expressions.is_empty() => template
411	            .quasis
412	            .first()
413	            .and_then(|quasi| quasi.value.cooked.as_ref())
414	            .map(|cooked| PropType::StringLiteral(js_text::lossy(*cooked).into_owned())),
415	        TSLiteral::TemplateLiteral(_) => None,
416	    }
417	}
418	
419	#[cfg(test)]
420	mod tests {
421	    use super::*;
422	
423	    fn written(source: &str) -> WrittenUnions {
424	        written_unions(camino::Utf8Path::new("/p/a.tsx"), source)
425	    }
426	
427	    fn lit(text: &str) -> WrittenMember {
428	        WrittenMember::Type(PropType::StringLiteral(text.into()))
429	    }
430	
431	    #[test]
432	    fn an_interface_member_writes_its_union_in_order() {
433	        let file = written("interface Props { size?: 'sm' | 'md' | 'lg'; on: boolean }");
434	        assert_eq!(file.find(Some("Props"), "size"), Some(&[lit("sm"), lit("md"), lit("lg")][..]));
435	        assert_eq!(file.find(Some("Props"), "on"), None);
436	        assert_eq!(file.find(None, "size"), None);
437	    }
438	
439	    #[test]
440	    fn a_same_file_alias_and_enum_are_flattened_where_they_are_named() {
441	        let file = written(
442	            "type Size = 'b' | 'a'\nenum Tone { Warm = 'w', Cold = 'c' }\n\
443	             interface Props { p: 'z' | Size | null; t?: Tone | -1 }",
444	        );
445	        assert_eq!(
446	            file.find(Some("Props"), "p"),
447	            Some(&[lit("z"), lit("b"), lit("a"), WrittenMember::Type(PropType::Null)][..])
448	        );
449	        assert_eq!(
450	            file.find(Some("Props"), "t"),
451	            Some(
452	                &[
453	                    WrittenMember::Name("Tone.Warm".into()),
454	                    WrittenMember::Name("Tone.Cold".into()),
455	                    WrittenMember::Type(PropType::NumberLiteral(-1.0)),
456	                ][..]
457	            )
458	        );
459	    }
460	
461	    #[test]
462	    fn an_imported_alias_stays_a_name_and_a_type_parameter_shadows_a_module_alias() {
463	        let file = written(
464	            "import type { Size } from './size'\ntype T = 'x' | 'y'\n\
465	             interface Props<T> { p: Size | 'a'; q: T | 'b' }",
466	        );
467	        assert_eq!(file.find(Some("Props"), "p"), Some(&[WrittenMember::Name("Size".into()), lit("a")][..]));
468	        assert_eq!(file.find(Some("Props"), "q"), Some(&[WrittenMember::Name("T".into()), lit("b")][..]));
469	    }
470	
471	    #[test]
472	    fn a_type_literal_member_has_no_interface_and_a_nested_one_is_not_a_prop() {
473	        let file = written(
474	            "export default function Icon(props: Base & { size?: 'L' | 'S' }) {}\n\
475	             interface Props { style: { size: 'x' | 'y' } }",
476	        );
477	        assert_eq!(file.find(None, "size"), Some(&[lit("L"), lit("S")][..]));
478	    }
479	
480	    #[test]
481	    fn two_declarations_that_write_different_unions_give_none() {
482	        let file = written("type A = { p: 'a' | 'b' }\ntype B = { p: 'b' | 'a' }");
483	        assert_eq!(file.find(None, "p"), None);
484	        let file = written("type A = { p: 'a' | 'b' }\ntype B = { p: 'a' | 'b' }");
485	        assert_eq!(file.find(None, "p"), Some(&[lit("a"), lit("b")][..]));
486	    }
487	
488	    #[test]
489	    fn members_written_only_by_kind_keep_their_kind() {
490	        let file = written(
491	            "interface Item { a: string }\ntype Wrap<T> = T[]\n\
492	             interface Props { p: (() => void) | { a: 1 } | [number] | Wrap<number> | Item | string[] | `x${string}` | ReadonlyArray<Item> }",
493	        );
494	        assert_eq!(
495	            file.find(Some("Props"), "p"),
496	            Some(
497	                &[
498	                    WrittenMember::Kind(MemberKind::Function),
499	                    WrittenMember::Kind(MemberKind::Object),
500	                    WrittenMember::Type(PropType::Tuple(vec![TupleElement::required(PropType::Number)])),
501	                    WrittenMember::Kind(MemberKind::Array),
502	                    WrittenMember::Kind(MemberKind::Object),
503	                    WrittenMember::Type(PropType::Array(Box::new(PropType::String))),
504	                    WrittenMember::Kind(MemberKind::Template),
505	                    WrittenMember::Kind(MemberKind::Readonly),
506	                ][..]
507	            )
508	        );
509	    }
510	
511	    #[test]
512	    fn a_recursive_alias_stops_where_it_names_itself() {
513	        let file = written("type Json = string | null | Json[]\ninterface Props { p?: Json }");
514	        assert_eq!(
515	            file.find(Some("Props"), "p"),
516	            Some(
517	                &[
518	                    WrittenMember::Type(PropType::String),
