1	//! What oxc reads from the source for the checker's answer (ADR 0026, S7a2): the defaults a component's own code gives
2	//! its props, and the order a prop's declaration writes its union in. The checker has neither (it keeps no parameter
3	//! initializer, and it sorts a union's members), and the structural resolver that supplied both goes in S7e.
4	//!
5	//! The files are the ones the answer names: the component's file, for its defaults and for the props a type literal
6	//! declares, and each union prop's `parent` file. Each is read and parsed once per merge.
7	
8	use std::sync::Arc;
9	
10	use camino::{Utf8Path, Utf8PathBuf};
11	use rayon::prelude::*;
12	use rustc_hash::FxHashMap;
13	
14	use super::SemanticProp;
15	use crate::extractor::written::{WrittenMember, WrittenUnions, written_unions};
16	use crate::types::collected::ComponentExport;
17	use crate::types::diagnostic::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
18	use crate::types::output::{ComponentEntry, DefaultValue, PropType};
19	
20	/// What a merge reads from one file.
21	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
22	struct Wanted {
23	    /// The defaults of the components it declares.
24	    defaults: bool,
25	    /// The unions its property signatures write.
26	    unions: bool,
27	}
28	
29	#[derive(Debug, Default)]
30	struct FileSyntax {
31	    /// Each component the extractor finds in the file: its name, its exports and its code defaults.
32	    components: Vec<(String, Vec<ComponentExport>, FxHashMap<String, DefaultValue>)>,
33	    unions: WrittenUnions,
34	}
35	
36	/// The syntax of the files one merge needs, read up front.
37	#[derive(Debug, Default)]
38	pub(super) struct SourceSyntax {
39	    files: FxHashMap<Utf8PathBuf, FileSyntax>,
40	    /// A file it could not read, other than one that does not exist on disk (a checker's bundled lib file).
41	    pub(super) diagnostics: Vec<Diagnostic>,
42	}
43	
44	impl SourceSyntax {
45	    /// Reads what the checker's `props` of each entry need: the entry's file, and the `parent` file of each prop whose
46	    /// type is a union. Files are read in parallel.
47	    pub(super) fn read<'a>(components: impl Iterator<Item = (&'a ComponentEntry, &'a [Arc<SemanticProp>])>) -> Self {
48	        let mut wanted: FxHashMap<Utf8PathBuf, Wanted> = FxHashMap::default();
49	        for (entry, props) in components {
50	            wanted.entry(entry.file_path.clone()).or_default().defaults = true;
51	            for prop in props.iter().filter(|prop| matches!(prop.prop_type, PropType::Union(_))) {
52	                let file = match &prop.parent {
