20	/// The property signatures of one file whose written type is a union of at least two members.
21	#[derive(Debug, Default)]
22	pub(crate) struct WrittenUnions {
23	    props: Vec<WrittenProp>,
24	}
25	
26	#[derive(Debug)]
27	struct WrittenProp {
28	    /// The interface whose body declares it; `None` for a member of a type literal.
29	    interface: Option<CompactString>,
30	    name: CompactString,
31	    members: Vec<WrittenMember>,
32	}
33	
34	/// One member of a written union, as far as the file states it.
35	#[derive(Debug, Clone, PartialEq)]
36	pub(crate) enum WrittenMember {
37	    /// A member the syntax states in full: a literal, a keyword, an array or tuple of those.
38	    Type(PropType),
39	    /// A reference to a type the file does not declare, as written (`React.ReactNode`, `Size.Small` for a member of an
40	    /// enum the file declares).
41	    Name(CompactString),
42	    /// A member of which only the kind is written: a function type, an object literal, an intersection.
43	    Kind(MemberKind),
44	}
45	
46	/// The kind of a union member whose type is not written out in full.
47	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
48	pub(crate) enum MemberKind {
49	    Function,
50	    Object,
51	    Callable,
52	    Array,
53	    Tuple,
54	    Readonly,
55	    Intersection,
56	    Template,
57	}
58	
59	impl WrittenUnions {
60	    /// The union written for prop `name` by the interface `interface` (`Some`) or by a type literal (`None`): the one
61	    /// every such declaration writes alike, or `None` when there is none or two write different unions.
62	    pub(crate) fn find(&self, interface: Option<&str>, name: &str) -> Option<&[WrittenMember]> {
63	        let mut found = self
64	            .props
65	            .iter()
66	            .filter(|prop| prop.name == name && prop.interface.as_deref() == interface)
67	            .map(|prop| prop.members.as_slice());
68	        let first = found.next()?;
69	        found.all(|other| other == first).then_some(first)
70	    }
71	}
72	
73	/// The written unions of `source`, the text of `path`. Empty for a file too deeply nested to parse safely.
74	pub(crate) fn written_unions(path: &camino::Utf8Path, source: &str) -> WrittenUnions {
75	    if super::max_bracket_nesting_depth(source) > super::MAX_SOURCE_NESTING_DEPTH {
76	        return WrittenUnions::default();
77	    }
78	    let allocator = Allocator::default();
79	    let source_type = SourceType::from_path(path).unwrap_or_default();
80	    let options = ParseOptions { preserve_parens: false, ..ParseOptions::default() };
81	    let parsed = Parser::new(&allocator, source, source_type).with_options(options).parse();
82	    let mut collector = Collector {
83	        declared: Declared::of(&parsed.program),
84	        owner: None,
85	        member_depth: 0,
86	        type_params: Vec::new(),
87	        props: Vec::new(),
88	    };
89	    collector.visit_program(&parsed.program);
90	    WrittenUnions { props: collector.props }
91	}
92	
93	/// The module-level declarations a union member can name: a name declared twice is in `ambiguous` and expands to
94	/// nothing.
95	#[derive(Default)]
96	struct Declared<'a, 's> {
97	    aliases: FxHashMap<&'s str, &'s TSTypeAliasDeclaration<'a>>,
98	    interfaces: FxHashSet<&'s str>,
99	    enums: FxHashMap<&'s str, Vec<CompactString>>,
100	    ambiguous: Vec<&'s str>,
101	}
102	
103	impl<'a, 's> Declared<'a, 's> {
104	    fn of(program: &'s Program<'a>) -> Self {
105	        let mut declared = Declared::default();
106	        for statement in &program.body {
107	            let declaration = match statement {
108	                Statement::ExportDeclaration(export) => Some(&export.declaration),
109	                _ => statement.as_declaration(),
110	            };
111	            match declaration {
112	                Some(Declaration::TSTypeAliasDeclaration(alias)) => {
113	                    let name = alias.id.name.as_str();
114	                    if declared.aliases.insert(name, &**alias).is_some() {
115	                        declared.ambiguous.push(name);
116	                    }
117	                }
118	                Some(Declaration::TSInterfaceDeclaration(interface)) => {
119	                    declared.interfaces.insert(interface.id.name.as_str());
120	                }
121	                Some(Declaration::TSEnumDeclaration(declaration)) => {
122	                    let members = declaration
123	                        .body
124	                        .members
125	                        .iter()
126	                        .filter_map(|member| match &member.id {
127	                            TSEnumMemberName::Identifier(id) => Some(CompactString::from(id.name.as_str())),
128	                            TSEnumMemberName::String(s) | TSEnumMemberName::ComputedString(s) => {
129	                                Some(CompactString::from(js_text::lossy(s.value).as_ref()))
130	                            }
131	                            TSEnumMemberName::ComputedTemplateString(_) => None,
132	                        })
133	                        .collect();
134	                    let name = declaration.id.name.as_str();
135	                    if declared.enums.insert(name, members).is_some() {
136	                        declared.ambiguous.push(name);
137	                    }
138	                }
139	                _ => {}
140	            }
141	        }
142	        declared
143	    }
144	}
145	
146	struct Collector<'a, 's> {
147	    declared: Declared<'a, 's>,
148	    /// The interface or type literal whose body is being read: `Some(Some(name))` for an interface.
149	    owner: Option<Option<CompactString>>,
150	    /// How many property signatures enclose the current node: a member of a type literal nested in another member's
151	    /// type is not a prop.
152	    member_depth: usize,
153	    /// The type parameters in scope, which shadow a module-level declaration of the same name.
154	    type_params: Vec<CompactString>,
155	    props: Vec<WrittenProp>,
156	}
157	
158	impl<'a> Visit<'a> for Collector<'a, '_> {
159	    fn visit_ts_interface_declaration(&mut self, it: &TSInterfaceDeclaration<'a>) {
160	        let scope = self.enter_type_params(it.type_parameters.as_deref());
161	        let owner = self.owner.replace(Some(CompactString::from(it.id.name.as_str())));
162	        walk::walk_ts_interface_declaration(self, it);
163	        self.owner = owner;
164	        self.type_params.truncate(scope);
165	    }
166	
167	    fn visit_ts_type_alias_declaration(&mut self, it: &TSTypeAliasDeclaration<'a>) {
168	        let scope = self.enter_type_params(it.type_parameters.as_deref());
169	        walk::walk_ts_type_alias_declaration(self, it);
170	        self.type_params.truncate(scope);
171	    }
172	
173	    fn visit_function(&mut self, it: &Function<'a>, flags: oxc_syntax::scope::ScopeFlags) {
174	        let scope = self.enter_type_params(it.type_parameters.as_deref());
175	        walk::walk_function(self, it, flags);
176	        self.type_params.truncate(scope);
177	    }
178	
179	    fn visit_arrow_function_expression(&mut self, it: &ArrowFunctionExpression<'a>) {
180	        let scope = self.enter_type_params(it.type_parameters.as_deref());
181	        walk::walk_arrow_function_expression(self, it);
182	        self.type_params.truncate(scope);
183	    }
184	
185	    fn visit_ts_type_literal(&mut self, it: &TSTypeLiteral<'a>) {
186	        let owner = self.owner.replace(None);
187	        walk::walk_ts_type_literal(self, it);
188	        self.owner = owner;
189	    }
190	
191	    fn visit_ts_property_signature(&mut self, it: &TSPropertySignature<'a>) {
192	        if self.member_depth == 0
193	            && let Some(owner) = &self.owner
194	            && let Some(name) = it.key.static_name()
195	            && let Some(annotation) = &it.type_annotation
196	        {
197	            let mut members = Vec::new();
198	            self.push_members(&annotation.type_annotation, &mut Vec::new(), &mut members);
199	            if members.len() > 1 {
200	                self.props.push(WrittenProp {
201	                    interface: owner.clone(),
202	                    name: CompactString::from(js_text::property_name(&name)),
203	                    members,
204	                });
205	            }
206	        }
207	        self.member_depth += 1;
208	        walk::walk_ts_property_signature(self, it);
209	        self.member_depth -= 1;
210	    }
211	}
