213	impl<'a> Collector<'a, '_> {
214	    fn enter_type_params(&mut self, params: Option<&TSTypeParameterDeclaration<'a>>) -> usize {
215	        let scope = self.type_params.len();
216	        for param in params.into_iter().flat_map(|params| &params.params) {
217	            self.type_params.push(CompactString::from(param.name.name.as_str()));
218	        }
219	        scope
220	    }
221	
222	    /// A module-level declaration named `name` that no type parameter in scope shadows and no other declaration shares.
223	    fn declares(&self, name: &str) -> bool {
224	        !self.type_params.iter().any(|param| param == name) && !self.declared.ambiguous.contains(&name)
225	    }
226	
227	    /// Appends the members `ty` writes, flattening a union and a same-file non-generic alias or enum it names. `seen`
228	    /// holds the aliases being expanded, so a recursive one (`type Json = string | Json[]`) stops.
229	    fn push_members<'s>(&'s self, ty: &'s TSType<'a>, seen: &mut Vec<&'s str>, out: &mut Vec<WrittenMember>) {
230	        match ty {
231	            TSType::TSUnionType(union) => {
232	                for member in &union.types {
233	                    self.push_members(member, seen, out);
234	                }
235	            }
236	            TSType::TSParenthesizedType(inner) => self.push_members(&inner.type_annotation, seen, out),
237	            TSType::TSTypeReference(reference) => {
238	                if let TSTypeName::IdentifierReference(id) = &reference.type_name
239	                    && reference.type_arguments.is_none()
240	                    && self.declares(id.name.as_str())
241	                {
242	                    let name = id.name.as_str();
243	                    if let Some(alias) = self.declared.aliases.get(name)
244	                        && alias.type_parameters.is_none()
245	                    {
246	                        if !seen.contains(&name) {
247	                            seen.push(name);
248	                            self.push_members(&alias.type_annotation, seen, out);
249	                            seen.pop();
250	                        }
251	                        return;
252	                    }
253	                    if let Some(members) = self.declared.enums.get(name) {
254	                        out.extend(members.iter().map(|member| WrittenMember::Name(format!("{name}.{member}").into())));
255	                        return;
256	                    }
257	                }
258	                out.extend(self.member(ty));
259	            }
260	            _ => out.extend(self.member(ty)),
261	        }
262	    }
263	
264	    /// One member as written; `None` for a type the syntax does not state (`typeof x`, `keyof T`, an indexed access, a
265	    /// conditional or mapped type).
266	    fn member(&self, ty: &TSType<'a>) -> Option<WrittenMember> {
267	        let written = |prop_type| Some(WrittenMember::Type(prop_type));
268	        let kind = |kind| Some(WrittenMember::Kind(kind));
269	        match ty {
270	            TSType::TSStringKeyword(_) => written(PropType::String),
271	            TSType::TSNumberKeyword(_) => written(PropType::Number),
272	            TSType::TSBooleanKeyword(_) => written(PropType::Boolean),
273	            TSType::TSNullKeyword(_) => written(PropType::Null),
274	            TSType::TSUndefinedKeyword(_) => written(PropType::Undefined),
275	            TSType::TSAnyKeyword(_) => written(PropType::Any),
276	            TSType::TSNeverKeyword(_) => written(PropType::Never),
277	            TSType::TSUnknownKeyword(_) => written(PropType::Unknown),
278	            TSType::TSVoidKeyword(_) => written(PropType::Void),
279	            TSType::TSBigIntKeyword(_) => written(PropType::BigInt),
280	            TSType::TSLiteralType(literal) => literal_type(&literal.literal).map(WrittenMember::Type),
281	            TSType::TSParenthesizedType(inner) => self.member(&inner.type_annotation),
282	            TSType::TSArrayType(array) => match self.member(&array.element_type) {
283	                Some(WrittenMember::Type(element)) => written(PropType::Array(Box::new(element))),
284	                _ => kind(MemberKind::Array),
285	            },
286	            TSType::TSTupleType(tuple) => {
287	                let elements: Option<Vec<TupleElement>> = tuple
288	                    .element_types
289	                    .iter()
290	                    .map(|element| match self.member(element.as_ts_type()?) {
291	                        Some(WrittenMember::Type(element)) => Some(TupleElement::required(element)),
292	                        _ => None,
293	                    })
294	                    .collect();
295	                match elements {
296	                    Some(elements) => written(PropType::Tuple(elements)),
297	                    None => kind(MemberKind::Tuple),
298	                }
299	            }
300	            TSType::TSTypeOperatorType(operator) => match operator.operator {
301	                TSTypeOperatorOperator::Readonly => match self.member(&operator.type_annotation) {
302	                    Some(WrittenMember::Type(inner)) => written(PropType::Readonly(Box::new(inner))),
303	                    _ => kind(MemberKind::Readonly),
304	                },
305	                TSTypeOperatorOperator::Keyof | TSTypeOperatorOperator::Unique => None,
306	            },
307	            TSType::TSFunctionType(_) | TSType::TSConstructorType(_) => kind(MemberKind::Function),
308	            TSType::TSTypeLiteral(_) | TSType::TSIntersectionType(_) | TSType::TSTemplateLiteralType(_) => {
309	                body_kind(ty).map(WrittenMember::Kind)
310	            }
311	            TSType::TSTypeReference(reference) => self.reference(reference),
312	            TSType::TSUnionType(_)
313	            | TSType::TSObjectKeyword(_)
314	            | TSType::TSSymbolKeyword(_)
315	            | TSType::TSIntrinsicKeyword(_)
316	            | TSType::TSThisType(_)
317	            | TSType::TSTypeQuery(_)
318	            | TSType::TSIndexedAccessType(_)
319	            | TSType::TSConditionalType(_)
320	            | TSType::TSMappedType(_)
321	            | TSType::TSInferType(_)
322	            | TSType::TSImportType(_)
323	            | TSType::TSTypePredicate(_)
324	            | TSType::TSNamedTupleMember(_)
325	            | TSType::JSDocNullableType(_)
326	            | TSType::JSDocNonNullableType(_)
327	            | TSType::JSDocUnknownType(_) => None,
328	        }
329	    }
330	
331	    /// A reference that is not a same-file alias of a union: the kind of a same-file interface or generic alias, an
332	    /// array type by its standard name, else the name as written.
333	    fn reference(&self, reference: &TSTypeReference<'a>) -> Option<WrittenMember> {
334	        let name = type_name(&reference.type_name);
335	        if let TSTypeName::IdentifierReference(id) = &reference.type_name
336	            && self.declares(id.name.as_str())
337	        {
338	            let name = id.name.as_str();
339	            if self.declared.interfaces.contains(name) {
340	                return Some(WrittenMember::Kind(MemberKind::Object));
341	            }
342	            if let Some(alias) = self.declared.aliases.get(name) {
343	                // A generic alias's members depend on its arguments, and a non-generic one named here is not flattened:
344	                // only the kind of its body is certain.
345	                return body_kind(&alias.type_annotation).map(WrittenMember::Kind);
346	            }
347	        }
348	        match name.as_str() {
349	            "Array" => Some(WrittenMember::Kind(MemberKind::Array)),
350	            "ReadonlyArray" => Some(WrittenMember::Kind(MemberKind::Readonly)),
351	            _ => Some(WrittenMember::Name(name)),
352	        }
353	    }
354	}
355	
356	/// The kind of a type as written at its top level, without following a name.
357	fn body_kind(ty: &TSType<'_>) -> Option<MemberKind> {
358	    match ty {
359	        TSType::TSArrayType(_) => Some(MemberKind::Array),
360	        TSType::TSTupleType(_) => Some(MemberKind::Tuple),
361	        TSType::TSFunctionType(_) | TSType::TSConstructorType(_) => Some(MemberKind::Function),
362	        TSType::TSTypeLiteral(literal) => Some(
363	            if literal.members.iter().any(|member| {
364	                matches!(
365	                    member,
366	                    TSSignature::TSCallSignatureDeclaration(_) | TSSignature::TSConstructSignatureDeclaration(_)
367	                )
368	            }) {
369	                MemberKind::Callable
370	            } else {
371	                MemberKind::Object
372	            },
373	        ),
374	        TSType::TSIntersectionType(_) => Some(MemberKind::Intersection),
375	        TSType::TSTemplateLiteralType(_) => Some(MemberKind::Template),
376	        TSType::TSTypeOperatorType(operator) if operator.operator == TSTypeOperatorOperator::Readonly => {
377	            Some(MemberKind::Readonly)
378	        }
379	        TSType::TSParenthesizedType(inner) => body_kind(&inner.type_annotation),
380	        _ => None,
381	    }
382	}
383	
384	fn type_name(name: &TSTypeName<'_>) -> CompactString {
385	    match name {
386	        TSTypeName::IdentifierReference(id) => CompactString::from(id.name.as_str()),
387	        TSTypeName::QualifiedName(qualified) => {
388	            let mut text = type_name(&qualified.left);
389	            text.push('.');
390	            text.push_str(qualified.right.name.as_str());
391	            text
392	        }
393	        TSTypeName::ThisExpression(_) => CompactString::from("this"),
394	    }
395	}
396	
397	fn literal_type(literal: &TSLiteral<'_>) -> Option<PropType> {
398	    match literal {
399	        TSLiteral::StringLiteral(s) => Some(PropType::StringLiteral(js_text::lossy(s.value).into_owned())),
400	        TSLiteral::NumericLiteral(n) => Some(PropType::NumberLiteral(n.value)),
401	        TSLiteral::BooleanLiteral(b) => Some(PropType::BoolLiteral(b.value)),
402	        TSLiteral::BigIntLiteral(b) => BigIntValue::parse(b.value.as_str()).map(PropType::BigIntLiteral),
403	        TSLiteral::UnaryExpression(unary) => match (&unary.operator, &unary.argument) {
404	            (UnaryOperator::UnaryNegation, Expression::NumericLiteral(n)) => Some(PropType::NumberLiteral(-n.value)),
405	            (UnaryOperator::UnaryNegation, Expression::BigIntLiteral(b)) => {
406	                BigIntValue::parse(&format!("-{}", b.value.as_str())).map(PropType::BigIntLiteral)
407	            }
408	            _ => None,
409	        },
410	        TSLiteral::TemplateLiteral(template) if template.expressions.is_empty() => template
411	            .quasis
412	            .first()
413	            .and_then(|quasi| quasi.value.cooked.as_ref())
414	            .map(|cooked| PropType::StringLiteral(js_text::lossy(*cooked).into_owned())),
415	        TSLiteral::TemplateLiteral(_) => None,
416	    }
417	}
