1	//! What oxc reads from the source for the checker's answer (ADR 0026, S7a2): the defaults a component's own code gives
2	//! its props, and the order a prop's declaration writes its union in. The checker has neither (it keeps no parameter
3	//! initializer, and it sorts a union's members), and the structural resolver that supplied both goes in S7e.
4	//!
5	//! The files are the ones the answer names: the component's file, for its defaults and for the props a type literal
6	//! declares, and each union prop's `parent` file. Each is read and parsed once per merge.
7	
8	use std::sync::Arc;
9	
10	use camino::{Utf8Path, Utf8PathBuf};
11	use rayon::prelude::*;
12	use rustc_hash::FxHashMap;
13	
14	use super::SemanticProp;
15	use crate::extractor::written::{WrittenMember, WrittenUnions, written_unions};
16	use crate::types::collected::ComponentExport;
17	use crate::types::diagnostic::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
18	use crate::types::output::{ComponentEntry, DefaultValue, PropType};
19	
20	/// What a merge reads from one file.
21	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
22	struct Wanted {
23	    /// The defaults of the components it declares.
24	    defaults: bool,
25	    /// The unions its property signatures write.
26	    unions: bool,
27	}
28	
29	#[derive(Debug, Default)]
30	struct FileSyntax {
31	    /// Each component the extractor finds in the file: its name, its exports and its code defaults.
32	    components: Vec<(String, Vec<ComponentExport>, FxHashMap<String, DefaultValue>)>,
33	    unions: WrittenUnions,
34	}
35	
36	/// The syntax of the files one merge needs, read up front.
37	#[derive(Debug, Default)]
38	pub(super) struct SourceSyntax {
39	    files: FxHashMap<Utf8PathBuf, FileSyntax>,
40	    /// A file it could not read, other than one that does not exist on disk (a checker's bundled lib file).
41	    pub(super) diagnostics: Vec<Diagnostic>,
42	}
43	
44	impl SourceSyntax {
45	    /// Reads what the checker's `props` of each entry need: the entry's file, and the `parent` file of each prop whose
46	    /// type is a union. Files are read in parallel.
47	    pub(super) fn read<'a>(components: impl Iterator<Item = (&'a ComponentEntry, &'a [Arc<SemanticProp>])>) -> Self {
48	        let mut wanted: FxHashMap<Utf8PathBuf, Wanted> = FxHashMap::default();
49	        for (entry, props) in components {
50	            wanted.entry(entry.file_path.clone()).or_default().defaults = true;
51	            for prop in props.iter().filter(|prop| matches!(prop.prop_type, PropType::Union(_))) {
52	                let file = match &prop.parent {
53	                    Some(parent) => Utf8PathBuf::from(&parent.file_name),
54	                    None => entry.file_path.clone(),
55	                };
56	                wanted.entry(file).or_default().unions = true;
57	            }
58	        }
59	        let read: Vec<(Utf8PathBuf, Result<FileSyntax, Option<Diagnostic>>)> = wanted
60	            .into_par_iter()
61	            .map(|(path, wanted)| {
62	                let file = read_file(&path, wanted);
63	                (path, file)
64	            })
65	            .collect();
66	        let mut syntax = SourceSyntax::default();
67	        for (path, file) in read {
68	            match file {
69	                Ok(file) => {
70	                    syntax.files.insert(path, file);
71	                }
72	                Err(diagnostic) => syntax.diagnostics.extend(diagnostic),
73	            }
74	        }
75	        syntax
76	    }
77	
78	    /// The defaults `entry`'s own code gives its props: those of the component the extractor finds in its file under
79	    /// its name and exports. `None` when the file has no such component, or several with different defaults.
80	    pub(super) fn code_defaults(&self, entry: &ComponentEntry) -> Option<&FxHashMap<String, DefaultValue>> {
81	        let file = self.files.get(&entry.file_path)?;
82	        let mut found = file
83	            .components
84	            .iter()
85	            .filter(|(name, exports, _)| *name == entry.display_name && *exports == entry.exports)
86	            .map(|(_, _, defaults)| defaults);
87	        let first = found.next()?;
88	        found.all(|other| other == first).then_some(first)
89	    }
90	
91	    /// The union `prop`'s declaration writes: in its `parent` interface, or for a prop with no parent, in a type literal
92	    /// of `entry`'s file. `None` when the file writes none for it, or two different ones.
93	    pub(super) fn written(&self, entry: &ComponentEntry, prop: &SemanticProp) -> Option<&[WrittenMember]> {
94	        match &prop.parent {
95	            Some(parent) => {
96	                self.files.get(Utf8Path::new(&parent.file_name))?.unions.find(Some(&parent.name), &prop.name)
97	            }
98	            None => self.files.get(&entry.file_path)?.unions.find(None, &prop.name),
99	        }
100	    }
101	}
102	
103	fn read_file(path: &Utf8Path, wanted: Wanted) -> Result<FileSyntax, Option<Diagnostic>> {
104	    let source = std::fs::read_to_string(path).map_err(|error| {
105	        (error.kind() != std::io::ErrorKind::NotFound).then(|| {
106	            let mut diagnostic = Diagnostic::new(
107	                DiagnosticSeverity::Warning,
108	                DiagnosticCode::SemanticBackend,
109	                format!(
110	                    "failed to read '{path}' for the defaults and union member order of the checker's answer: {error}"
111	                ),
112	            );
113	            diagnostic.file = Some(path.to_string());
114	            diagnostic
115	        })
116	    })?;
117	    let mut file = FileSyntax::default();
118	    if wanted.defaults {
119	        file.components = crate::extractor::parse_file(path, &source)
120	            .component_mappings
121	            .into_iter()
122	            .map(|mapping| {
123	                let defaults = mapping
124	                    .param_defaults
125	                    .into_iter()
126	                    .map(|(name, raw)| (name, DefaultValue { value: raw.value, computed: raw.computed }))
127	                    .collect();
128	                (mapping.component_name, mapping.exports, defaults)
129	            })
130	            .collect();
131	    }
132	    if wanted.unions {
133	        file.unions = written_unions(path, &source);
134	    }
135	    Ok(file)
136	}
