341	/// Merges the checker's `props` into `entry` by name: the checker's type, optionality, description, tags, `parent` and
342	/// `declarations` win where both have a prop, and every structural prop the checker did not return stays as the
343	/// structural pass resolved it. `composes` replaces the entry's when the checker decided it, and an undecided one leaves
344	/// the structural `composes` ([`SemanticComponent::composes`]). A prop whose checker
345	/// type holds an `opaque` part, where the structural type holds none, keeps the structural type and adds the checker's
346	/// reasons to its `degradedBy`: the checker's answer there is a placeholder, and the structural one is not confirmed,
347	/// so it is marked. A type the checker only cut at a limit (`truncated`) is still its answer.
348	///
349	/// Two facts the checker does not have come from oxc's syntax, read from the files the answer names: a prop's default
350	/// (the component's code: a destructured parameter's initializer, `defaultProps`; else the checker's `@default` tag)
351	/// and the order of a union's members (the order its declaration writes them in). The structural answer gives them
352	/// where the syntax does not tell ([`ResolverFacts::Used`]).
353	pub fn merge_semantic_props<'a>(
354	    entry: &mut ComponentEntry,
355	    props: impl Iterator<Item = &'a Arc<SemanticProp>>,
356	    composes: Option<&[String]>,
357	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
358	) -> MergedProps {
359	    let props: Vec<Arc<SemanticProp>> = props.cloned().collect();
360	    let syntax = SourceSyntax::read(std::iter::once((&*entry, props.as_slice())));
361	    let merge = Merge { composes, unanswered: Unanswered::Keep, syntax: &syntax, resolver: ResolverFacts::Used };
362	    let mut merged = replace_props(entry, props.iter(), &merge, shared);
363	    merged.diagnostics = syntax.diagnostics;
364	    merged
365	}
366	
367	/// The kinds of what the checker could not read in `checker`, when the structural type `structural` read everything:
368	/// then the structural type is kept and marked with them. Empty when the checker's type is its answer.
369	fn unread_by_checker(checker: &PropType, structural: &PropType) -> Vec<&'static str> {
370	    let unread: Vec<&'static str> = checker.degraded_by().into_iter().filter(|kind| *kind != TRUNCATED_KIND).collect();
371	    if unread.is_empty() || structural.degraded_by().iter().any(|kind| *kind != TRUNCATED_KIND) {
372	        return Vec::new();
373	    }
374	    unread
375	}
376	
377	/// The one diagnostic for the props of `affects` that kept their structural type because the checker could not read it
378	/// ([`MergedProps::unread`]); each such prop says why in its `degradedBy`.
379	pub(crate) fn unread_diagnostic(props: usize, affects: Vec<String>) -> Diagnostic {
380	    let mut diagnostic = Diagnostic::new(
381	        DiagnosticSeverity::Info,
382	        DiagnosticCode::SemanticBackend,
383	        format!(
384	            "{props} prop(s) of {} component(s) keep their structural type: the TypeScript checker could not read it, \
385	             and their degradedBy says what it could not read",
386	            affects.len()
387	        ),
388	    );
389	    diagnostic.affects = affects;
390	    diagnostic
391	}
392	
393	/// What a merge does with a structural prop the checker did not return.
394	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
395	enum Unanswered {
396	    /// The checker decides which props exist, as in the whole-project merge: the structural prop is dropped.
397	    Drop,
398	    /// The checker's props are merged by name, as in a session's merge: the structural prop stays as resolved.
399	    Keep,
400	}
401	
402	/// How one merge reads what the checker does not answer.
403	struct Merge<'a> {
404	    composes: Option<&'a [String]>,
405	    unanswered: Unanswered,
406	    syntax: &'a SourceSyntax,
407	    resolver: ResolverFacts,
408	}
409	
410	/// A prop's default: the component's code default for it, else the checker's `@default` (or `@defaultValue`) tag, else
411	/// with [`ResolverFacts::Used`] the structural default. The code wins over the tag, as in react-docgen-typescript.
412	fn default_of(
413	    code: Option<&DefaultValue>,
414	    checker_tags: &BTreeMap<String, String>,
415	    structural: Option<&ParsedProp>,
416	    resolver: ResolverFacts,
417	) -> Option<DefaultValue> {
418	    if let Some(code) = code {
419	        return Some(code.clone());
420	    }
421	    let tag = checker_tags.get("default").or_else(|| checker_tags.get("defaultValue"));
422	    if let Some(tag) = tag {
423	        return Some(DefaultValue { value: tag.trim().to_owned(), computed: false });
424	    }
425	    match resolver {
426	        ResolverFacts::Used => structural.and_then(|structural| structural.default_value.clone()),
427	        ResolverFacts::Off => None,
428	    }
429	}
430	
431	/// The checker's type with its union members in declared order: the order the declaration writes them in where it
432	/// states every member, else the structural union's order where that placed any member (with
433	/// [`ResolverFacts::Used`]), else the written order of the members the declaration does state. Neither leaves the
434	/// checker's order.
435	fn declared_order(
436	    checker: PropType,
437	    written: Option<&[WrittenMember]>,
438	    structural: Option<&ParsedProp>,
439	    resolver: ResolverFacts,
440	) -> PropType {
441	    let structural = match resolver {
442	        ResolverFacts::Used => structural,
443	        ResolverFacts::Off => None,
444	    };
445	    // The structural order also reaches the unions nested in members, which the written one does not.
446	    let (ordered, reordered) = match structural {
447	        Some(structural) => {
448	            let ordered = order::in_declared_order(checker.clone(), &structural.prop_type);
449	            let reordered = ordered != checker;
450	            (ordered, reordered)
451	        }
452	        None => (checker, false),
453	    };
454	    match written.and_then(|written| order::in_written_order(&ordered, written)) {
455	        Some((in_written, Placed::All)) => in_written,
456	        Some((in_written, Placed::Some)) if !reordered => in_written,
457	        Some(_) | None => ordered,
458	    }
459	}
460	
461	fn replace_props<'a>(
462	    entry: &mut ComponentEntry,
463	    props_in: impl Iterator<Item = &'a Arc<SemanticProp>>,
464	    merge: &Merge<'_>,
465	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
466	) -> MergedProps {
467	    let Merge { composes, unanswered, syntax, resolver } = *merge;
468	    let code_defaults = syntax.code_defaults(entry);
469	    let mut props: BTreeMap<String, Arc<ParsedProp>> = BTreeMap::new();
470	    let mut unread = 0;
471	    for prop in props_in {
472	        let structural = entry.props.get(&prop.name);
473	        let description = if prop.description.is_empty() {
474	            structural.map(|s| s.description.clone()).unwrap_or_default()
475	        } else {
476	            prop.description.clone()
477	        };
478	        let tags = if prop.tags.is_empty() {
479	            structural.map(|s| s.tags.clone()).unwrap_or_default()
480	        } else {
481	            prop.tags.clone()
482	        };
483	        let unread_kinds = structural.map(|s| unread_by_checker(&prop.prop_type, &s.prop_type)).unwrap_or_default();
484	        let prop_type = match structural {
485	            Some(structural) if !unread_kinds.is_empty() => structural.prop_type.clone(),
486	            Some(_) | None => {
487	                declared_order(prop.prop_type.clone(), syntax.written(entry, prop), structural.map(|s| &**s), resolver)
488	            }
489	        };
490	        unread += usize::from(!unread_kinds.is_empty());
491	        let merged = ParsedProp::new(
492	            prop.name.clone(),
493	            prop_type,
494	            prop.required,
495	            default_of(
496	                code_defaults.and_then(|defaults| defaults.get(&prop.name)),
497	                &prop.tags,
498	                structural.map(|s| &**s),
499	                resolver,
500	            ),
501	            description,
502	            tags,
503	            prop.parent.clone(),
504	            prop.declarations.clone(),
505	        )
506	        .degraded_also_by(&unread_kinds);
507	        let mut hasher = FxHasher::default();
508	        merged.structural_hash(&mut hasher);
509	        let bucket = shared.entry(hasher.finish()).or_default();
510	        let merged = match bucket.iter().find(|existing| ***existing == merged) {
511	            Some(existing) => existing.clone(),
512	            None => {
513	                let merged = Arc::new(merged);
514	                bucket.push(merged.clone());
515	                merged
516	            }
517	        };
518	        props.insert(prop.name.clone(), merged);
519	    }
520	    let mut kept = 0;
521	    if unanswered == Unanswered::Keep {
522	        for (name, structural) in &entry.props {
523	            if !props.contains_key(name) {
524	                props.insert(name.clone(), structural.clone());
525	                kept += 1;
526	            }
527	        }
528	    }
529	    entry.props = props;
530	    if let Some(composes) = composes {
531	        entry.composes = composes.to_vec();
532	    }
533	    MergedProps { kept, unread, diagnostics: Vec::new() }
534	}
