536	/// Merge the checker's props over `output`, component by component.
537	///
538	/// Per `docs/type-checker-integration.md`: the checker decides which props exist, their types, whether they are
539	/// required, `parent`, `declarations` and the component's `composes`; a description and tags come from the checker,
540	/// else the structural pass; a default value and a union's member order come from oxc's syntax, else the structural
541	/// pass ([`merge_semantic_props`]). Inheritance layers, curated inherited props and `discriminantProp` stay structural. Components the checker
542	/// did not answer for keep their structural result untouched.
543	///
544	/// Records provenance as `Info` diagnostics whose `affects` lists the output keys, so the canonical JSON gains no
545	/// field: one for the components the checker resolved, one per fallback reason.
546	pub fn merge_semantic(output: &mut ExtractionOutput, outcome: SemanticOutcome) {
547	    merge_semantic_with(output, outcome, ResolverFacts::Used);
548	}
549	
550	/// [`merge_semantic`], taking the facts the checker does not supply from the structural answer only as `resolver`
551	/// allows.
552	pub fn merge_semantic_with(output: &mut ExtractionOutput, outcome: SemanticOutcome, resolver: ResolverFacts) {
553	    let SemanticOutcome { components, fallbacks, diagnostics } = outcome;
554	    let syntax = SourceSyntax::read(
555	        components
556	            .iter()
557	            .filter_map(|semantic| Some((output.components.get(&semantic.key)?, semantic.props.as_slice()))),
558	    );
559	    let mut merged_keys = Vec::new();
560	    let (mut unread_keys, mut unread_props) = (Vec::new(), 0);
561	    let mut shared: FxHashMap<u64, Vec<Arc<ParsedProp>>> = FxHashMap::default();
562	    for semantic in components {
563	        let Some(entry) = output.components.get_mut(&semantic.key) else { continue };
564	        let unread = apply_props(entry, &semantic, &mut shared, &syntax, resolver).unread;
565	        if unread > 0 {
566	            unread_props += unread;
567	            unread_keys.push(semantic.key.clone());
568	        }
569	        merged_keys.push(semantic.key);
570	    }
571	    output.diagnostics.extend(diagnostics);
572	    output.diagnostics.extend(syntax.diagnostics);
573	
574	    // A structural diagnostic about a prop the checker now answers for would be stale; the resolved component keeps
575	    // none of its degrade diagnostics.
576	    if !merged_keys.is_empty() {
577	        output.diagnostics.retain(|diagnostic| {
578	            let degrade = matches!(
579	                diagnostic.code,
580	                DiagnosticCode::OpaqueType | DiagnosticCode::MaxDepthExceeded | DiagnosticCode::CircularReference
581	            );
582	            !(degrade
583	                && !diagnostic.affects.is_empty()
584	                && diagnostic.affects.iter().all(|key| merged_keys.contains(key)))
585	        });
586	        merged_keys.sort();
587	        let mut provenance = Diagnostic::new(
588	            DiagnosticSeverity::Info,
589	            DiagnosticCode::SemanticBackend,
590	            format!("{} component(s) resolved by the TypeScript checker", merged_keys.len()),
591	        );
592	        provenance.affects = merged_keys;
593	        output.diagnostics.push(provenance);
594	    }
595	    if !unread_keys.is_empty() {
596	        unread_keys.sort();
597	        output.diagnostics.push(unread_diagnostic(unread_props, unread_keys));
598	    }
599	
600	    let mut by_reason: BTreeMap<String, Vec<String>> = BTreeMap::new();
601	    for SemanticFallback { key, reason } in fallbacks {
602	        if output.components.contains_key(&key) {
603	            by_reason.entry(reason).or_default().push(key);
604	        }
605	    }
606	    for (reason, mut keys) in by_reason {
607	        keys.sort();
608	        let mut diagnostic = Diagnostic::new(
609	            DiagnosticSeverity::Info,
610	            DiagnosticCode::SemanticBackend,
611	            format!("{} component(s) kept their structural result: {reason}", keys.len()),
612	        );
613	        diagnostic.affects = keys;
614	        output.diagnostics.push(diagnostic);
615	    }
616	}
