1	//! Declaration order for a union the checker answered.
2	//!
3	//! The checker builds a union's members sorted by kind, then by value, so `"sm" | "md" | "lg"` comes back as
4	//! `"lg" | "md" | "sm"`; the order the author wrote is not in its answer, and it is the order a Storybook control lists
5	//! its options in. Two sources give it back, and the merge picks between them (`declared_order` in the parent module):
6	//!
7	//! - **oxc's syntax** ([`in_written_order`]): the union the prop's declaration writes, read from the file the checker
8	//!   names (`crate::extractor::written`). It orders the top-level union only, and a member written as a name the file
9	//!   does not declare (an import) places nothing: the members it stands for keep their place after the placed ones.
10	//! - **the structural resolver** ([`in_declared_order`]): where the structural pass resolved the same union, its order
11	//!   is the declared one, nested unions included. It goes with the resolver (ADR 0026, S7e).
12	//!
13	//! Only a reorder is made: no member is added, dropped or changed. A union neither source orders keeps the checker's
14	//! order (by kind, then value): not alphabetical, and not marked.
15	
16	use crate::extractor::written::{MemberKind, WrittenMember};
17	use crate::types::output::{ObjectField, PropType};
18	
19	/// `checker` with the members of every union it shares with `declared` put in `declared`'s order.
20	pub(super) fn in_declared_order(checker: PropType, declared: &PropType) -> PropType {
21	    match (checker, declared) {
22	        (PropType::Union(members), PropType::Union(order)) => PropType::Union(reorder(members, order)),
23	        // A union of string literals the structural pass keeps as their values (`type Size = "sm" | "lg"`).
24	        (PropType::Union(members), PropType::LiteralUnion { members: values, .. }) => {
25	            let order: Vec<PropType> = values.iter().map(|value| PropType::StringLiteral(value.clone())).collect();
26	            PropType::Union(reorder(members, &order))
27	        }
28	        (PropType::Array(inner), PropType::Array(declared)) => {
29	            PropType::Array(Box::new(in_declared_order(*inner, declared)))
30	        }
31	        (PropType::Readonly(inner), PropType::Readonly(declared)) => {
32	            PropType::Readonly(Box::new(in_declared_order(*inner, declared)))
33	        }
34	        (PropType::Intersection(members), PropType::Intersection(declared)) if members.len() == declared.len() => {
35	            PropType::Intersection(zip_ordered(members, declared))
36	        }
37	        (PropType::Tuple(elements), PropType::Tuple(declared)) if elements.len() == declared.len() => PropType::Tuple(
38	            elements
39	                .into_iter()
40	                .zip(declared)
41	                .map(|(mut element, declared)| {
42	                    element.element_type = in_declared_order(element.element_type, &declared.element_type);
43	                    element
44	                })
45	                .collect(),
46	        ),
47	        (PropType::Object(fields), PropType::Object(declared)) => PropType::Object(ordered_fields(fields, declared)),
48	        (
49	            PropType::Function { type_params, params, return_type },
50	            PropType::Function { params: declared_params, return_type: declared_return, .. },
51	        ) if params.len() == declared_params.len() => PropType::Function {
52	            type_params,
53	            params: params
54	                .into_iter()
55	                .zip(declared_params)
56	                .map(|(mut param, declared)| {
57	                    param.param_type = in_declared_order(param.param_type, &declared.param_type);
58	                    param
59	                })
60	                .collect(),
61	            return_type: Box::new(in_declared_order(*return_type, declared_return)),
62	        },
63	        (other, _) => other,
64	    }
65	}
66	
67	/// How many of a union's members the written order placed.
68	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
69	pub(super) enum Placed {
70	    All,
71	    Some,
72	}
73	
74	/// `checker`'s union with the members `written` states put in its order, then the others in their order in `checker`.
75	/// A member is placed by the written member that states it (a literal, a keyword, a name it answers to), else by kind
76	/// when the written union has one member of that kind and the checker one unplaced member of it. `None` when `checker`
77	/// is not a union or `written` places none of its members.
78	pub(super) fn in_written_order(checker: &PropType, written: &[WrittenMember]) -> Option<(PropType, Placed)> {
79	    let PropType::Union(members) = checker else { return None };
80	    let mut places: Vec<Option<usize>> =
81	        members.iter().map(|member| written.iter().position(|candidate| states(candidate, member))).collect();
82	    for index in 0..members.len() {
83	        if places[index].is_some() {
84	            continue;
85	        }
86	        let Some(kind) = kind_of(&members[index]) else { continue };
87	        let unplaced_of_kind = members
88	            .iter()
89	            .zip(&places)
90	            .filter(|(member, place)| place.is_none() && kind_of(member) == Some(kind))
91	            .count();
92	        let mut slots = written.iter().enumerate().filter(|(_, candidate)| **candidate == WrittenMember::Kind(kind));
93	        if let (Some((slot, _)), None) = (slots.next(), slots.next())
94	            && unplaced_of_kind == 1
95	        {
96	            places[index] = Some(slot);
97	        }
98	    }
99	    if places.iter().all(Option::is_none) {
100	        return None;
101	    }
102	    let placed = if places.iter().all(Option::is_some) { Placed::All } else { Placed::Some };
103	    let (mut known, unknown): (Vec<_>, Vec<_>) =
104	        members.iter().cloned().zip(places).partition(|(_, place)| place.is_some());
105	    known.sort_by_key(|(_, place)| *place);
106	    Some((PropType::Union(known.into_iter().chain(unknown).map(|(member, _)| member).collect()), placed))
107	}
108	
109	/// Whether the written member `written` states the checker's member `member`.
110	fn states(written: &WrittenMember, member: &PropType) -> bool {
111	    match written {
112	        // `boolean` is `true | false` to the checker; the source may have written either.
113	        WrittenMember::Type(written) => {
114	            written == member || (*member == PropType::Boolean && matches!(written, PropType::BoolLiteral(_)))
115	        }
116	        WrittenMember::Name(name) => answers_to(member, name),
117	        WrittenMember::Kind(_) => false,
118	    }
119	}
120	
121	/// Whether the checker's member is the type the source names `written` (`React.ReactNode`, `Size.Small`), by the name
122	/// without the namespace it was written through: the checker names the declaration.
123	fn answers_to(member: &PropType, written: &str) -> bool {
124	    let bare = |name: &str| name.rsplit('.').next().unwrap_or(name).to_owned();
125	    let written_bare = bare(written);
126	    match member {
127	        PropType::Named { name, .. } | PropType::Recursive { name, .. } => bare(name) == written_bare,
128	        PropType::EnumMember { enum_name, member, .. } => {
129	            written.strip_suffix(member.as_str()).and_then(|head| head.strip_suffix('.')).map(bare)
130	                == Some(bare(enum_name))
131	        }
132	        PropType::Ref { name, .. } => *name == written_bare,
133	        PropType::ReactNode => {
134	            matches!(written_bare.as_str(), "ReactNode" | "ReactElement") || written == "JSX.Element"
135	        }
136	        PropType::CssProperties => written_bare == "CSSProperties",
137	        PropType::ElementType => written_bare == "ElementType",
138	        _ => false,
139	    }
140	}
141	
142	/// The kind a member written only by its kind has on the checker's side.
143	fn kind_of(member: &PropType) -> Option<MemberKind> {
144	    match member {
145	        PropType::Function { .. } => Some(MemberKind::Function),
146	        PropType::Callable { .. } => Some(MemberKind::Callable),
147	        PropType::Object(_) => Some(MemberKind::Object),
148	        PropType::Array(_) => Some(MemberKind::Array),
149	        PropType::Tuple(_) => Some(MemberKind::Tuple),
150	        PropType::Readonly(_) => Some(MemberKind::Readonly),
151	        PropType::Intersection(_) => Some(MemberKind::Intersection),
152	        PropType::TemplateLiteral(_) => Some(MemberKind::Template),
153	        _ => None,
154	    }
155	}
156	
157	fn zip_ordered(members: Vec<PropType>, declared: &[PropType]) -> Vec<PropType> {
158	    members.into_iter().zip(declared).map(|(member, declared)| in_declared_order(member, declared)).collect()
159	}
160	
161	fn ordered_fields(fields: Vec<ObjectField>, declared: &[ObjectField]) -> Vec<ObjectField> {
162	    fields
163	        .into_iter()
164	        .map(|mut field| {
165	            let counterpart = declared.iter().find(|candidate| {
166	                candidate.name == field.name && candidate.index_key.is_some() == field.index_key.is_some()
167	            });
168	            if let Some(counterpart) = counterpart {
169	                field.prop_type = in_declared_order(field.prop_type, &counterpart.prop_type);
170	            }
171	            field
172	        })
173	        .collect()
174	}
175	
176	/// The members the declaration also has, in its order, then the members it does not have, in the checker's order: the
177	/// checker's place for them is its sort, not the source's, and a member the structural pass dropped is most often the
178	/// `undefined` or `null` written last. Unchanged when the declaration has none of them.
179	fn reorder(members: Vec<PropType>, declared: &[PropType]) -> Vec<PropType> {
180	    let bare = |name: &str| name.rsplit('.').next().unwrap_or(name).to_owned();
181	    let position = |member: &PropType| {
182	        declared.iter().position(|candidate| candidate == member).or_else(|| match member {
183	            // `boolean` is `true | false` to the checker; the source may have written either.
184	            PropType::Boolean => declared.iter().position(|candidate| matches!(candidate, PropType::BoolLiteral(_))),
185	            // The source may name a type through a namespace (`React.Ref`); the checker names the declaration.
186	            PropType::Named { name, .. } => declared.iter().position(
187	                |candidate| matches!(candidate, PropType::Named { name: written, .. } if bare(written) == bare(name)),
188	            ),
189	            _ => None,
190	        })
191	    };
192	    let places: Vec<Option<usize>> = members.iter().map(position).collect();
193	    if places.iter().all(Option::is_none) {
194	        return members;
195	    }
196	    let (mut known, unknown): (Vec<_>, Vec<_>) =
197	        members.into_iter().zip(places).partition(|(_, place)| place.is_some());
198	    known.sort_by_key(|(_, place)| *place);
199	    known.into_iter().chain(unknown).map(|(member, _)| member).collect()
200	}
